        for r in range(min(rows), max(rows) + 1):
            if out[r][spine_col] == 0:
                out[r][spine_col] = 3
        for r, c in points:
            step = 1 if spine_col >= c else -1
            for x in range(c, spine_col + step, step):
                if out[r][x] == 0:
                    out[r][x] = 3
    else:
        spine_row = sorted(rows)[len(rows) // 2]
        for c in range(min(cols), max(cols) + 1):
            if out[spine_row][c] == 0:
                out[spine_row][c] = 3
        for r, c in points:
